From 882ad035d9720fec04672a89a8223466140ba1c0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:03:43 +0100
Subject: [PATCH] ExpandableListItem: resize the view's highlight together with
 the item

While the item animated its height, the list view restarted its own
highlight resize animation on every frame, so the highlight lagged behind
the content when expanding and collapsing. Set its height directly instead.

BUG: 494153
---
 .../plasmaextracomponents/qml/ExpandableListItem.qml      | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml b/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
index 168c4f6f5..4453ea3dd 100644
--- a/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
+++ b/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
@@ -342,6 +342,14 @@ Item {
     }
     clip: heightAnimation.running || expandedItemOpacityFade.running

+    // Resize the highlight with us, or the view keeps restarting its own animation and it lags behind
+    onHeightChanged: {
+        const view = listItem.ListView.view;
+        if (heightAnimation.running && view && view.currentItem === listItem && view.highlightItem) {
+            view.highlightItem.height = listItem.height;
+        }
+    }
+
     onEnabledChanged: if (!listItem.enabled) { listItem.collapse() }

     Keys.onPressed: event => {
-- 
